<script setup lang="ts">
import PageNotice from '../components/PageNotice.vue';
import ScrollTable from '../components/ScrollTable.vue';
import { scaledPopupProps } from '../utils/scaled-popup';
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {useI18n} from 'vue-i18n';import {useRoute} from 'vue-router';import {session} from '../services/api';
import {listEngagements,getEngagement,reviewDelivery,publishDelivery,withdrawDelivery,listFiles,type Engagement,type EngagementDetail,type FileRecord,OperationError} from '../services/operations';import {formatJst} from '../services/audit';import OperationsError from '../components/operations/OperationsError.vue';import OperationsFile from '../components/operations/OperationsFile.vue';
const success=ref(false),successRun=ref(0);
const {t,te}=useI18n(),route=useRoute();const projects=ref<Engagement[]>([]),detail=ref<EngagementDetail|null>(null),selected=ref(''),offset=ref(0),busy=ref(false),error=ref<unknown>(null),checks=ref([false,false,false,false]),evidence=ref(''),tab=ref('delivery'),dialog=ref<'approved'|'changes_requested'|'publish'|'withdraw'|null>(null),fileId=ref(''),fileVisible=ref(false),files=ref<FileRecord[]>([]),fileOffset=ref(0),fileStatus=ref('pending');
const delivery=computed(()=>detail.value?.deliveries.at(-1)),review=computed(()=>detail.value?.reviews.find(r=>r.delivery_id===delivery.value?.id)),canReview=computed(()=>session.account?.roles.some(r=>['administrator','quality_reviewer'].includes(r))),canInspect=computed(()=>session.account?.roles.some(r=>['administrator','operator'].includes(r)));const status=(v:string)=>te(`ops.api.status.${v}`)?t(`ops.api.status.${v}`):v;const columns=computed(()=>[{colKey:'original_name',title:t('ops.delivery.file')},{colKey:'size_bytes',title:t('ops.api.size'),width:110},{colKey:'actions',title:t('ops.details'),width:80}]);let run=0,listRun=0,fileRun=0;
async function loadList(){const n=++listRun;busy.value=true;error.value=null;try{const page=await listEngagements(offset.value);if(n!==listRun)return;projects.value=page.items;if(!selected.value)selected.value=offset.value===0&&typeof route.query.id==='string'?route.query.id:projects.value[0]?.id??'';if(selected.value)await loadDetail();else detail.value=null}catch(e){if(n===listRun){error.value=e;projects.value=[];detail.value=null}}finally{if(n===listRun)busy.value=false}}async function loadDetail(){const n=++run;busy.value=true;error.value=null;detail.value=null;checks.value=[false,false,false,false];evidence.value='';try{const value=await getEngagement(selected.value);if(n===run)detail.value=value}catch(e){if(n===run)error.value=e}finally{if(n===run)busy.value=false}}

async function loadFiles(){const n=++fileRun;busy.value=true;error.value=null;files.value=[];try{const page=await listFiles(fileOffset.value,fileStatus.value);if(n===fileRun)files.value=page.items}catch(e){if(n===fileRun)error.value=e}finally{if(n===fileRun)busy.value=false}}
watch(tab,()=>{++fileRun;error.value=null;if(tab.value==='files')loadFiles();else busy.value=false});
function ask(action:'approved'|'changes_requested'|'publish'|'withdraw'){success.value=false;error.value=null;if(action==='approved'&&!checks.value.every(Boolean)){error.value=new OperationError('checklistRequired');return}if(action!=='publish'&&!evidence.value.trim()){error.value=new OperationError('reasonRequired');return}dialog.value=action}
async function confirm(){if(!detail.value||!delivery.value||!dialog.value)return;success.value=false;busy.value=true;error.value=null;try{const e=detail.value.engagement,d=delivery.value;if(dialog.value==='publish')await publishDelivery(e.id,d.id,e.row_version);else if(dialog.value==='withdraw')await withdrawDelivery(e.id,d.id,e.row_version,evidence.value);else await reviewDelivery(e.id,d.id,e.row_version,dialog.value,evidence.value,checks.value);dialog.value=null;success.value=true;++successRun.value;await loadDetail()}catch(e){error.value=e;dialog.value=null}finally{busy.value=false}}
function openFile(id:string){fileId.value=id;fileVisible.value=true}onMounted(loadList);onBeforeUnmount(()=>{++run;++listRun;++fileRun});
</script>
<template><div class="page-stack module-page"><OperationsError :error="error"/><PageNotice v-if="success" :key="successRun" theme="success" :message="t('ops.api.saved')" @close="success=false"/><t-tabs v-model="tab"><t-tab-panel value="delivery" :label="t('ops.delivery.fixed')"/><t-tab-panel v-if="canInspect" value="files" :label="t('ops.api.fileQueue')"/></t-tabs>
<template v-if="tab==='delivery'"><t-card :bordered="false" class="section-card"><div class="table-toolbar"><label>{{t('ops.api.selectProject')}}</label><t-select :popup-props="scaledPopupProps" v-model="selected" style="min-width:280px;flex:1" :options="[...projects,...(detail&&!projects.some(p=>p.id===detail?.engagement.id)?[detail.engagement]:[])].map(p=>({label:`${p.public_code} · ${status(p.status)}`,value:p.id}))" :disabled="busy" @change="loadDetail"/><t-button :loading="busy" variant="outline" @click="loadList">{{t('ops.api.refresh')}}</t-button><t-button :disabled="!offset||busy" variant="text" @click="offset-=20;selected='';loadList()">{{t('ops.api.previous')}}</t-button><t-button :disabled="projects.length<20||busy" variant="text" @click="offset+=20;selected='';loadList()">{{t('ops.api.next')}}</t-button></div><t-empty v-if="!projects.length&&!detail&&!busy&&!error" :description="t('ops.api.noProjects')"/></t-card><t-empty v-if="detail&&!delivery" :description="t('ops.api.noDelivery')"/>
<div v-if="detail&&delivery" class="two-column module-scroll"><t-card :title="t('ops.delivery.fixed')" :bordered="false" class="section-card"><div class="page-stack"><t-descriptions :column="1"><t-descriptions-item :label="t('ops.delivery.projectVersion')">{{detail.engagement.public_code}} / v{{delivery.version}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.rowVersion')">{{detail.engagement.row_version}}</t-descriptions-item><t-descriptions-item :label="t('ops.delivery.submitted')">{{formatJst(delivery.submitted_at)}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.repository')"><span class="readable">{{delivery.repository_url||'—'}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.commit')"><span class="mono readable">{{delivery.source_commit||'—'}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.archive')">{{delivery.source_archive_ref||'—'}}</t-descriptions-item></t-descriptions><section v-for="field in (['note','guide_text','test_report_text'] as const)" :key="field"><h3>{{t(`ops.api.${{note:'note',guide_text:'guide',test_report_text:'tests'}[field]}`)}}</h3><p class="readable">{{delivery[field]}}</p></section><t-table :max-height="320" row-key="id" :data="delivery.files" :columns="columns" :empty="t('ops.api.empty')"><template #size_bytes="{row}">{{row.size_bytes.toLocaleString()}} B</template><template #actions="{row}"><t-link theme="primary" @click="openFile(row.id)">{{t('ops.details')}}</t-link></template></t-table><t-button v-if="delivery.source_file_id&&!delivery.files.some(f=>f.id===delivery?.source_file_id)" variant="outline" @click="openFile(delivery.source_file_id)">{{t('ops.delivery.source')}}</t-button></div></t-card>
<t-card :title="t('ops.delivery.checklist')" :bordered="false" class="section-card"><div class="page-stack"><t-tag :theme="delivery.published?'success':'warning'" variant="light">{{delivery.published?t('ops.api.published'):t('ops.api.unpublished')}}</t-tag><PageNotice v-if="review" notification theme="info" :message="t('ops.api.reviewLocked')"/><template v-if="review"><strong>{{t('ops.api.review')}} · {{status(review.decision)}}</strong><p class="readable">{{review.evidence}}</p><p class="mono readable">{{review.reviewer_id}}</p></template><template v-if="!review&&canReview&&detail.engagement.status==='internal_review'"><t-checkbox v-for="index in 4" :key="index" v-model="checks[index-1]" :disabled="busy">{{t(`ops.delivery.checks.${index-1}`)}}</t-checkbox></template><template v-if="canReview&&((!review&&detail.engagement.status==='internal_review')||delivery.published)"><label>{{t('ops.api.reviewEvidence')}}</label><t-textarea v-model="evidence" :maxlength="delivery.published?2000:12000" :autosize="{minRows:4,maxRows:10}"/><PageNotice notification theme="info" :message="t('ops.api.evidenceHint')"/></template><PageNotice notification theme="info" :message="t('ops.delivery.boundary')"/><t-space v-if="canReview" break-line><template v-if="!review&&detail.engagement.status==='internal_review'"><t-button :disabled="busy" theme="primary" @click="ask('approved')">{{t('ops.api.approve')}}</t-button><t-button :disabled="busy" theme="danger" variant="outline" @click="ask('changes_requested')">{{t('ops.api.changes')}}</t-button></template><t-button v-if="review?.decision==='approved'&&detail.engagement.status==='internal_review'&&!detail.publications.some(p=>p.delivery_id===delivery?.id)" :disabled="busy" @click="ask('publish')">{{t('ops.api.publish')}}</t-button><t-button v-if="delivery.published&&['awaiting_acceptance','revision'].includes(detail.engagement.status)" :disabled="busy" theme="danger" @click="ask('withdraw')">{{t('ops.api.withdraw')}}</t-button></t-space></div></t-card></div></template>
<t-card v-else :title="t('ops.api.fileQueue')" :bordered="false" class="section-card list-card"><div class="table-toolbar"><t-select :popup-props="scaledPopupProps" v-model="fileStatus" style="width:180px" :options="['pending','clean','rejected','failed'].map(v=>({label:status(v),value:v}))" @change="fileOffset=0;loadFiles()"/><t-button :loading="busy" variant="outline" @click="loadFiles">{{t('ops.api.refresh')}}</t-button></div><ScrollTable row-key="id" :data="files" :columns="columns" :empty="t('ops.api.empty')"><template #size_bytes="{row}">{{row.size_bytes.toLocaleString()}} B</template><template #actions="{row}"><t-link theme="primary" @click="openFile(row.id)">{{t('ops.details')}}</t-link></template></ScrollTable><t-space><t-button :disabled="!fileOffset||busy" @click="fileOffset-=20;loadFiles()">{{t('ops.api.previous')}}</t-button><t-button :disabled="files.length<20||busy" @click="fileOffset+=20;loadFiles()">{{t('ops.api.next')}}</t-button></t-space></t-card>
<t-dialog :visible="dialog!==null" :header="t('ops.api.confirmAction')" :confirm-btn="{content:t('ops.confirm'),loading:busy}" :cancel-btn="t('ops.cancel')" @close="dialog=null" @confirm="confirm"><PageNotice inline theme="info" :message="t('ops.api.confirmWrite')"/><p>{{detail?.engagement.public_code}} · v{{delivery?.version}} · {{dialog==='publish'?t('ops.api.publish'):dialog==='withdraw'?t('ops.api.withdraw'):status(dialog||'')}}</p><p class="readable">{{evidence}}</p></t-dialog><t-drawer v-model:visible="fileVisible" :header="t('ops.api.fileInfo')" :close-btn="true" :footer="false" size="520px" destroy-on-close><OperationsFile v-if="fileVisible" :file-id="fileId" @changed="tab==='files'?loadFiles():loadDetail()"/></t-drawer></div></template>
<style scoped>h3{font-size:14px;margin-bottom:10px}.t-checkbox :deep(.t-checkbox__label){white-space:normal}.readable{overflow-wrap:anywhere}</style>



